```json
{
  "source_url": "https://github.com/ethereum/EIPs/blob/master/EIPS/eip-7594.md",
  "title": "EIP-7594: PeerDAS - Peer Data Availability Sampling",
  "category": "EIP",
  "type": "Standards Track / Core",
  "status": "Final",
  "layer": "consensus+networking",
  "sub_graphs": [
    {
      "id": "SG-7594-001",
      "name": "1D Erasure Coding Extension",
      "description": "Extends EIP-4844 blobs using one-dimensional erasure coding. Each row is blob data plus erasure code, subdivided into cells. Each column (associated with a gossip subnet) consists of cells from all rows for a specific index.",
      "invariants": [
        {"id": "INV-7594-001", "text": "Each cell can be individually authenticated against its respective blob's KZG commitment."},
        {"id": "INV-7594-002", "text": "The entire data matrix is reconstructable if at least 50% of all columns are acquired."},
        {"id": "INV-7594-003", "text": "Each node maintains a deterministic set of column subnets as a function of their node ID."}
      ],
      "functions": [],
      "state_variables": [
        {"id": "SV-7594-001", "name": "CELLS_PER_EXT_BLOB", "description": "Number of cells for an extended blob, defined in consensus specs."},
        {"id": "SV-7594-002", "name": "NUMBER_OF_CUSTODY_GROUPS", "description": "Total number of samples/columns possible in the DAS scheme."},
        {"id": "SV-7594-003", "name": "SAMPLES_PER_SLOT", "description": "Minimum number of samples a node must download per slot."}
      ],
      "data_structures": [],
      "preconditions": [],
      "postconditions": []
    },
    {
      "id": "SG-7594-002",
      "name": "Column Custody and Peer Sampling",
      "description": "Nodes find and maintain a diverse peer set and sample columns from peers to perform DAS every slot. Validators have additional custody requirements that scale with validator count.",
      "invariants": [
        {"id": "INV-7594-004", "text": "Each node MUST custody a deterministic set of column subnets derived from its node ID."},
        {"id": "INV-7594-005", "text": "Validators MUST meet additional custody requirements beyond full node requirements, scaling with validator count."},
        {"id": "INV-7594-006", "text": "A node with less than 50% of columns can request the necessary columns from its peer nodes."}
      ],
      "functions": [],
      "state_variables": [],
      "data_structures": [],
      "preconditions": [
        {"id": "PRE-7594-001", "text": "Node must have a diverse peer set before sampling."}
      ],
      "postconditions": [
        {"id": "POST-7594-001", "text": "After sampling, node has verified data availability for the slot."}
      ]
    },
    {
      "id": "SG-7594-003",
      "name": "Blob Transaction Wrapper Modification",
      "description": "Modifies the EIP-4844 transaction pool wrapper to include cell KZG proofs and a wrapper version byte. Transaction senders compute cell proofs and include them in the wrapper.",
      "invariants": [
        {"id": "INV-7594-007", "text": "cell_proofs MUST contain exactly CELLS_PER_EXT_BLOB * len(blobs) cell proofs."},
        {"id": "INV-7594-008", "text": "Blobs are sent without being extended (CELLS_PER_EXT_BLOB / 2 cells per blob) to avoid redundant data."},
        {"id": "INV-7594-009", "text": "wrapper_version MUST be set to 1 for the current version."}
      ],
      "functions": [
        {"id": "FN-7594-001", "signature": "compute_cells(blob) -> cells[]", "description": "Outputs all cells of a blob, including extension cells."},
        {"id": "FN-7594-002", "signature": "verify_cell_kzg_proof_batch(commitments, cell_proofs) -> bool", "description": "Batch verifies all cell KZG proofs at once."},
        {"id": "FN-7594-003", "signature": "kzg_to_versioned_hash(commitment) -> versioned_hash", "description": "Converts a KZG commitment to a versioned hash."}
      ],
      "state_variables": [],
      "data_structures": [
        {"id": "DS-7594-001", "name": "BlobTransactionWrapper", "definition": "rlp([tx_payload_body, wrapper_version, blobs, commitments, cell_proofs])"},
        {"id": "DS-7594-002", "name": "cell_proofs", "definition": "list of cell proofs: [cell_proof_0, cell_proof_1, ...]"},
        {"id": "DS-7594-003", "name": "wrapper_version", "definition": "One byte indicating wrapper version, currently set to 1"}
      ],
      "preconditions": [
        {"id": "PRE-7594-002", "text": "Transaction sender MUST compute cell proofs before submission."}
      ],
      "postconditions": []
    },
    {
      "id": "SG-7594-004",
      "name": "Transaction Validation Rules",
      "description": "Defines mandatory validation rules for blob transaction wrappers, including commitment matching, proof counts, and the 6-blob-per-transaction limit.",
      "invariants": [
        {"id": "INV-7594-010", "text": "There MUST be an equal number of tx_payload_body.blob_versioned_hashes, blobs, and commitments."},
        {"id": "INV-7594-011", "text": "kzg_to_versioned_hash(commitments[i]) MUST equal tx_payload_body.blob_versioned_hashes[i] for all i."},
        {"id": "INV-7594-012", "text": "KZG commitments MUST match corresponding blobs and cell_proofs via compute_cells and verify_cell_kzg_proof_batch."},
        {"id": "INV-7594-013", "text": "A maximum of 6 blobs per transaction MUST be enforced at submission, network receipt, and block production/processing."}
      ],
      "functions": [],
      "state_variables": [],
      "data_structures": [],
      "preconditions": [
        {"id": "PRE-7594-003", "text": "tx_payload_body must be valid per EIP-4844 rules."}
      ],
      "postconditions": [
        {"id": "POST-7594-002", "text": "All wrapper validation checks pass before transaction acceptance."}
      ]
    },
    {
      "id": "SG-7594-005",
      "name": "Data Withholding Attack Resistance",
      "description": "Security model for PeerDAS against data withholding attacks. Uses randomized sampling to make attack probability negligible as network size grows.",
      "invariants": [
        {"id": "INV-7594-014", "text": "Attack success probability decreases super-linearly with the number of target nodes (epsilon * n)."},
        {"id": "INV-7594-015", "text": "For mainnet parameters (n=10000), probability of tricking >2% of nodes is bounded by 10^-20."},
        {"id": "INV-7594-016", "text": "Reconstruction threshold requires at least 50% of columns (m/2 out of m total)."}
      ],
      "functions": [],
      "state_variables": [],
      "data_structures": [],
      "preconditions": [],
      "postconditions": []
    }
  ],
  "metadata": {
    "timestamp": "1770265501",
    "extraction_method": "manual_analysis",
    "spec_references": [
      "https://github.com/ethereum/consensus-specs/tree/9d377fd53d029536e57cfda1a4d2c700c59f86bf/specs/fulu/"
    ]
  }
}
```

